file_reset(struct magic_set *ms, int checkloaded)
{
        if (checkloaded && ms->mlist[0] == NULL) {
                file_error(ms, 0, "no magic files loaded");
                return -1;
        }
        file_clearbuf(ms);
        if (ms->o.pbuf) {
                free(ms->o.pbuf);
                ms->o.pbuf = NULL;
        }
        ms->event_flags &= ~EVENT_HAD_ERR;
        ms->error = -1;
        return 0;
}

